import unittest
from candidate import max_element

class TestMaxElement(unittest.TestCase):
    def test_max_element_normalcase_expectedbehavior(self):
        self.assertEqual(max_element([1, 2, 3]), 3)

    def test_max_element_empty_list(self):
        self.assertIsNone(max_element([]))

    def test_max_element_single_element(self):
        self.assertEqual(max_element([5]), 5)

    def test_max_element_multiple_maximum_elements(self):
        self.assertEqual(max_element([5, 3, 5]), 5)

    def test_max_element_negative_numbers(self):
        self.assertEqual(max_element([-1, -2, -3]), -1)

    def test_max_element_mixed_numbers(self):
        self.assertEqual(max_element([-1, 0, 3]), 3)

    def test_max_element_float_numbers(self):
        self.assertAlmostEqual(max_element([1.5, 2.5, 3.5]), 3.5)

    def test_max_element_with_none(self):
        self.assertIsNone(max_element([None]))

    def test_max_element_with_non_list(self):
        self.assertRaises(TypeError, max_element, 5)

    def test_max_element_list_with_none_and_integer(self):
        self.assertEqual(max_element([1, None]), 1)

if __name__ == '__main__':
    unittest.main()
